const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
const asArray = (v) => Array.isArray(v) ? v : [];
const toStr = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s ? s : null;
};
const normPhone = (v) => {
  const s = String(v || "").replace(/\D/g, "");
  if (!s) return null;
  if (s.length === 10) return "7" + s;
  if (s.length === 11 && s.startsWith("8")) return "7" + s.slice(1);
  return s;
};
const uniq = (arr) => Array.from(new Set(arr.filter(Boolean)));

const body = isObj(msg.payload) ? msg.payload : {};
const nowIso = new Date().toISOString();

const booking = isObj(body.booking) ? body.booking : {};
const payment = isObj(body.payment) ? body.payment : {};
const settings = isObj(body.settings) ? body.settings : {};
const invite = isObj(body.invite) ? body.invite : {};
const metadata = isObj(body.metadata) ? body.metadata : {};
const organizer = isObj(body.organizer) ? body.organizer : {};

const normalizePlayer = (p, fallbackSource) => {
  if (!isObj(p)) return null;
  const phone = normPhone(p.phone || p.phoneNumber || p.mobile);
  return {
    id: toStr(p.id || p.clientId || p.userId || p.uuid),
    name: toStr(p.name || p.fullName || [p.firstName, p.lastName].filter(Boolean).join(" ")) || "Игрок",
    phone,
    photo: toStr(p.photo || p.avatar || p.imageUrl),
    rating: toStr(p.rating || p.level || p.grade),
    source: toStr(p.source || fallbackSource || "INVITED"),
    status: toStr(p.status || "CONFIRMED"),
  };
};

const participants = asArray(body.participants).map((p) => normalizePlayer(p, "INVITED")).filter(Boolean);
const waitlist = asArray(body.waitlist).map((p) => normalizePlayer(p, "WAITLIST")).filter(Boolean);

const organizerPhone = normPhone(organizer.phone || organizer.phoneNumber || body.clientPhone || body.phone);
const organizerNorm = {
  id: toStr(organizer.id || organizer.clientId || body.clientId),
  name: toStr(organizer.name || [organizer.firstName, organizer.lastName].filter(Boolean).join(" ")) || "Организатор",
  phone: organizerPhone,
  phoneNorm: organizerPhone,
  photo: toStr(organizer.photo || organizer.avatar || body.profilePhoto),
  rating: toStr(organizer.rating || organizer.level || body.profileGrade),
};

const studioId = toStr(booking.studioId || body.studioId);
const roomId = toStr(booking.roomId || body.roomId);
const date = toStr(booking.date || body.fromDate);
const timeFrom = toStr(booking.timeFrom || body.fromTime);
const timeTo = toStr(booking.timeTo || body.toTime);

const subServiceIds = uniq([
  ...asArray(booking.subServiceIds),
  ...asArray(body.subServiceIds),
].map((v) => toStr(v))).filter(Boolean).sort();

const toIso = (baseDate, baseTime, explicitIso) => {
  const iso = toStr(explicitIso);
  if (iso) return iso;
  if (!baseDate || !baseTime) return null;
  const normalizedTime = /^\d{2}:\d{2}$/.test(baseTime) ? `${baseTime}:00` : baseTime;
  return `${baseDate}T${normalizedTime}+03:00`;
};

const startIso = toIso(date, timeFrom, booking.timeFromIso || body.timeFromIso);
const endIso = toIso(date, timeTo, booking.timeToIso || body.timeToIso);

const startTs = startIso ? Date.parse(startIso) : null;
const endTs = endIso ? Date.parse(endIso) : null;

const vivaExerciseId = toStr(
  booking.vivaExerciseId || booking.exerciseId || metadata.vivaExerciseId || metadata.exerciseId,
);

const slotKey = [studioId, roomId, date, timeFrom, timeTo, subServiceIds.join(",")].join("|");
const dedupeKey = vivaExerciseId ? `viva:${vivaExerciseId}` : `slot:${slotKey}`;

const fallbackId = dedupeKey.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 120);
const gameId = toStr(body.id || body.gameId || body.recordId) || fallbackId || (`g_${Date.now()}`);

const invitedPhonesFromPayload = uniq([
  ...asArray(body.invitedPhones).map((v) => normPhone(v)),
  ...asArray(body.invites).map((it) => normPhone(isObj(it) ? (it.phone || it.phoneNumber) : it)),
]);

const participantPhones = uniq(participants.map((p) => normPhone(p.phone)));
const waitlistPhones = uniq(waitlist.map((p) => normPhone(p.phone)));
const allRelatedPhones = uniq([
  organizerPhone,
  ...participantPhones,
  ...waitlistPhones,
  ...invitedPhonesFromPayload,
]);

const record = {
  id: gameId,
  tenantKey: toStr(body.tenantKey) || null,
  source: toStr(body.source) || "padlhub_lk",
  dedupeKey,
  createdByFlow: true,
  status: toStr(body.status) || "PAID",
  organizer: organizerNorm,
  booking: {
    studioId,
    studioName: toStr(booking.studioName),
    masterServiceId: toStr(booking.masterServiceId),
    subServiceIds,
    roomId,
    roomName: toStr(booking.roomName),
    date,
    timeFrom,
    timeTo,
    timeFromIso: startIso,
    timeToIso: endIso,
    startTs,
    endTs,
    durationMinutes: Number.isFinite(Number(booking.durationMinutes)) ? Number(booking.durationMinutes) : null,
    slotId: toStr(booking.slotId),
    vivaExerciseId,
  },
  payment: {
    amount: Number.isFinite(Number(payment.amount)) ? Number(payment.amount) : null,
    paymentUrl: toStr(payment.paymentUrl || payment.paymentLink || payment.url),
    paymentMethod: toStr(payment.paymentMethod || "WIDGET"),
    baseRedirectUrl: toStr(payment.baseRedirectUrl),
    paid: typeof payment.paid === "boolean" ? payment.paid : true,
    paidAt: toStr(payment.paidAt) || nowIso,
  },
  settings: {
    ratingGame: typeof settings.ratingGame === "boolean" ? settings.ratingGame : null,
    minRating: toStr(settings.minRating),
    maxRating: toStr(settings.maxRating),
    isPrivate: typeof settings.isPrivate === "boolean" ? settings.isPrivate : null,
    payMode: toStr(settings.payMode),
  },
  invite: {
    inviteUrl: toStr((isObj(body.invite) ? body.invite.inviteUrl : null) || body.inviteUrl),
    waitlistEnabled: typeof invite.waitlistEnabled === "boolean" ? invite.waitlistEnabled : true,
    maxPlayers: Number.isFinite(Number(invite.maxPlayers)) ? Number(invite.maxPlayers) : 4,
  },
  participants,
  waitlist,
  participantPhones,
  waitlistPhones,
  invitedPhones: invitedPhonesFromPayload,
  allRelatedPhones,
  chatUrl: toStr(body.chatUrl),
  metadata,
  archived: Boolean(body.archived),
  updatedAt: nowIso,
};

const dbMsg = Object.assign({}, msg, {
  query: { dedupeKey },
  payload: {
    $set: record,
    $setOnInsert: {
      id: gameId,
      createdAt: nowIso,
    },
  },
});

const responseMsg = Object.assign({}, msg, {
  statusCode: 200,
  headers: { "Content-Type": "application/json; charset=utf-8" },
  payload: Object.assign({ createdAt: nowIso }, record),
});

return [dbMsg, responseMsg, responseMsg];

const normPhone = (v) => {
  const s = String(v || "").replace(/\D/g, "");
  if (!s) return null;
  if (s.length === 10) return "7" + s;
  if (s.length === 11 && s.startsWith("8")) return "7" + s.slice(1);
  return s;
};

const q = msg.req?.query || {};
const phone = normPhone(q.phone || q.phoneNumber || q.userPhone || q.mobile);
if (!phone) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "phone is required" };
  return [null, msg, msg];
}

const includePast = String(q.includePast || "").toLowerCase() === "true";
const nowTs = Date.now();

const mongoQuery = {
  archived: { $ne: true },
  $or: [
    { "organizer.phoneNorm": phone },
    { allRelatedPhones: phone },
    { participantPhones: phone },
    { waitlistPhones: phone },
    { invitedPhones: phone },
  ],
};

if (!includePast) {
  mongoQuery.$and = [
    {
      $or: [
        { "booking.endTs": { $gte: nowTs } },
        {
          $and: [
            { "booking.endTs": { $exists: false } },
            { "booking.startTs": { $gte: nowTs } },
          ],
        },
        {
          $and: [
            { "booking.endTs": { $exists: false } },
            { "booking.startTs": { $exists: false } },
          ],
        },
      ],
    },
  ];
}

msg._lkPhone = phone;
msg._lkIncludePast = includePast;
msg.payload = mongoQuery;
return [msg, null, msg];

const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
const normPhone = (v) => {
  const s = String(v || "").replace(/\D/g, "");
  if (!s) return null;
  if (s.length === 10) return "7" + s;
  if (s.length === 11 && s.startsWith("8")) return "7" + s.slice(1);
  return s;
};
const uniq = (arr) => Array.from(new Set(arr.filter(Boolean)));
const asArray = (v) => Array.isArray(v) ? v : [];

const phone = msg._lkPhone || null;
const includePast = Boolean(msg._lkIncludePast);
const nowTs = Date.now();

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const byKey = new Map();

const getTs = (doc) => {
  const endTs = Number(doc?.booking?.endTs);
  const startTs = Number(doc?.booking?.startTs);
  return Number.isFinite(startTs) ? startTs : (Number.isFinite(endTs) ? endTs : Number.MAX_SAFE_INTEGER);
};

const getUpdateTs = (doc) => {
  const ts = Date.parse(doc?.updatedAt || doc?.createdAt || "");
  return Number.isFinite(ts) ? ts : 0;
};

const collectPhones = (doc) => {
  const organizerPhone = normPhone(doc?.organizer?.phoneNorm || doc?.organizer?.phone);
  const pPhones = asArray(doc?.participants).map((p) => normPhone(p?.phone));
  const wPhones = asArray(doc?.waitlist).map((p) => normPhone(p?.phone));
  return uniq([
    organizerPhone,
    ...asArray(doc?.allRelatedPhones).map((p) => normPhone(p)),
    ...asArray(doc?.participantPhones).map((p) => normPhone(p)),
    ...asArray(doc?.waitlistPhones).map((p) => normPhone(p)),
    ...asArray(doc?.invitedPhones).map((p) => normPhone(p)),
    ...pPhones,
    ...wPhones,
  ]);
};

rows.forEach((doc) => {
  if (!isObj(doc)) return;

  const status = String(doc.status || "").toUpperCase();
  if (status.includes("CANCEL")) return;

  const endTs = Number(doc?.booking?.endTs);
  if (!includePast && Number.isFinite(endTs) && endTs < nowTs) return;

  const phones = collectPhones(doc);
  if (phone && phones.length > 0 && !phones.includes(phone)) return;

  const vivaId = doc?.booking?.vivaExerciseId || doc?.metadata?.vivaExerciseId || doc?.metadata?.exerciseId || null;
  const slotFallback = [
    doc?.booking?.studioId || "",
    doc?.booking?.roomId || "",
    doc?.booking?.date || "",
    doc?.booking?.timeFrom || "",
    doc?.booking?.timeTo || "",
    asArray(doc?.booking?.subServiceIds).join(","),
  ].join("|");

  const dedupeKey = vivaId ? `viva:${vivaId}` : (doc.dedupeKey || `slot:${slotFallback}`);
  const prev = byKey.get(dedupeKey);

  if (!prev) {
    byKey.set(dedupeKey, doc);
    return;
  }

  if (getUpdateTs(doc) >= getUpdateTs(prev)) {
    byKey.set(dedupeKey, doc);
  }
});

const games = Array.from(byKey.values()).sort((a, b) => getTs(a) - getTs(b));

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
  phone,
  total: games.length,
  games,
};

return [msg, msg];

const gameId = String(msg.req?.params?.gameId || "").trim();
if (!gameId) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "gameId is required" };
  return [null, msg];
}

msg.payload = { id: gameId, archived: { $ne: true } };
return [msg, null];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length === 0) {
  msg.statusCode = 404;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "Game not found" };
  return [msg, msg];
}

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = rows[0];
return [msg, msg];

const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
const asArray = (v) => Array.isArray(v) ? v : [];
const toStr = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s ? s : null;
};
const normPhone = (v) => {
  const s = String(v || "").replace(/\D/g, "");
  if (!s) return null;
  if (s.length === 10) return "7" + s;
  if (s.length === 11 && s.startsWith("8")) return "7" + s.slice(1);
  return s;
};
const uniq = (arr) => Array.from(new Set(arr.filter(Boolean)));

const gameId = String(msg.req?.params?.gameId || "").trim();
if (!gameId) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "gameId is required" };
  return [null, msg, msg];
}

const body = isObj(msg.payload) ? msg.payload : {};
const nowIso = new Date().toISOString();
const setDoc = {};

const assignIfPresent = (key) => {
  if (Object.prototype.hasOwnProperty.call(body, key)) {
    setDoc[key] = body[key];
  }
};

["status", "chatUrl", "inviteUrl", "metadata", "settings", "payment", "invite", "archived"].forEach(assignIfPresent);

if (isObj(body.organizer)) {
  setDoc.organizer = Object.assign({}, body.organizer, {
    phone: normPhone(body.organizer.phone || body.organizer.phoneNumber || body.organizer.mobile),
    phoneNorm: normPhone(body.organizer.phone || body.organizer.phoneNumber || body.organizer.mobile),
  });
}

if (isObj(body.booking)) {
  const b = Object.assign({}, body.booking);
  const date = toStr(b.date);
  const timeFrom = toStr(b.timeFrom);
  const timeTo = toStr(b.timeTo);
  const toIso = (baseDate, baseTime, explicitIso) => {
    const iso = toStr(explicitIso);
    if (iso) return iso;
    if (!baseDate || !baseTime) return null;
    const normalizedTime = /^\d{2}:\d{2}$/.test(baseTime) ? `${baseTime}:00` : baseTime;
    return `${baseDate}T${normalizedTime}+03:00`;
  };
  const startIso = toIso(date, timeFrom, b.timeFromIso);
  const endIso = toIso(date, timeTo, b.timeToIso);

  b.timeFromIso = startIso;
  b.timeToIso = endIso;
  b.startTs = startIso ? Date.parse(startIso) : b.startTs;
  b.endTs = endIso ? Date.parse(endIso) : b.endTs;

  setDoc.booking = b;
}

const normalizePlayer = (p, fallbackSource) => {
  if (!isObj(p)) return null;
  return {
    id: toStr(p.id || p.clientId || p.userId || p.uuid),
    name: toStr(p.name || p.fullName || [p.firstName, p.lastName].filter(Boolean).join(" ")) || "Игрок",
    phone: normPhone(p.phone || p.phoneNumber || p.mobile),
    photo: toStr(p.photo || p.avatar || p.imageUrl),
    rating: toStr(p.rating || p.level || p.grade),
    source: toStr(p.source || fallbackSource || "INVITED"),
    status: toStr(p.status || "CONFIRMED"),
  };
};

if (Array.isArray(body.participants)) {
  setDoc.participants = body.participants.map((p) => normalizePlayer(p, "INVITED")).filter(Boolean);
}
if (Array.isArray(body.waitlist)) {
  setDoc.waitlist = body.waitlist.map((p) => normalizePlayer(p, "WAITLIST")).filter(Boolean);
}

const shouldRecalcPhones = isObj(body.organizer)
  || Array.isArray(body.participants)
  || Array.isArray(body.waitlist)
  || Array.isArray(body.invitedPhones)
  || Array.isArray(body.invites);

if (shouldRecalcPhones) {
  const organizerPhone = normPhone((setDoc.organizer || body.organizer || {}).phone);
  const participants = asArray(setDoc.participants || body.participants);
  const waitlist = asArray(setDoc.waitlist || body.waitlist);
  const participantPhones = uniq(participants.map((p) => normPhone(p.phone)));
  const waitlistPhones = uniq(waitlist.map((p) => normPhone(p.phone)));
  const invitedPhones = uniq([
    ...asArray(body.invitedPhones).map((v) => normPhone(v)),
    ...asArray(body.invites).map((it) => normPhone(isObj(it) ? (it.phone || it.phoneNumber) : it)),
  ]);

  setDoc.participantPhones = participantPhones;
  setDoc.waitlistPhones = waitlistPhones;
  setDoc.invitedPhones = invitedPhones;
  setDoc.allRelatedPhones = uniq([
    organizerPhone,
    ...participantPhones,
    ...waitlistPhones,
    ...invitedPhones,
  ]);
}

setDoc.updatedAt = nowIso;

if (Object.keys(setDoc).length === 1 && setDoc.updatedAt) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "Empty patch" };
  return [null, msg, msg];
}

const dbMsg = Object.assign({}, msg, {
  query: { id: gameId, archived: { $ne: true } },
  payload: { $set: setDoc },
});

const responseMsg = Object.assign({}, msg, {
  statusCode: 200,
  headers: { "Content-Type": "application/json; charset=utf-8" },
  payload: Object.assign({ id: gameId }, setDoc),
});

return [dbMsg, responseMsg, responseMsg];
